#!/usr/bin/env bash
# orfs.sh - run the OpenROAD stage of the flow in the ORFS Podman container.
#
# The container image is a prebuilt OpenROAD-flow-scripts. No build step.
# The repo mounts at /repo, the foundry outputs at /work. Generated by
# netbuild: foundry/tech.lef, foundry/netlist.v.
#
# usage: flow/orfs.sh [tcl file]     # default flow/factorilog.tcl

set -euo pipefail

cd "$(git rev-parse --show-toplevel)"
IMAGE="docker.io/openroad/orfs:latest"
TCL="${1:-flow/factorilog.tcl}"

exec podman run --rm \
    --security-opt label=disable \
    -v "$PWD":/repo \
    -v "$PWD/foundry":/work \
    -w /work \
    "$IMAGE" \
    bash -lc "source /OpenROAD-flow-scripts/env.sh >/dev/null && openroad -no_init -exit /repo/$TCL"